selector_to_html = {"a[href=\"#platform-prerequisites\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Platform prerequisites<a class=\"headerlink\" href=\"#platform-prerequisites\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#prepare-flagscale\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Prepare FlagScale<a class=\"headerlink\" href=\"#prepare-flagscale\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#prepare-the-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Prepare the environment<a class=\"headerlink\" href=\"#prepare-the-environment\" title=\"Link to this heading\">#</a></h2><h3>3.1 Get the image and start the container<a class=\"headerlink\" href=\"#get-the-image-and-start-the-container\" title=\"Link to this heading\">#</a></h3><p>Go to the <a class=\"reference external\" href=\"https://flagos.io/Home\">FlagOS main page</a>, pick the image for your hardware from the download list in the middle of the page, and follow the on-page instructions to pull the image, enter the container, and start it.</p><p>Before installing the packages below, check inside the container that your device is visible (section 2 lists the command for each platform).</p>", "a[href=\"#install-megatron-lm-fl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Install Megatron-LM-FL<a class=\"headerlink\" href=\"#install-megatron-lm-fl\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">10. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../references/reference.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">References<a class=\"headerlink\" href=\"#references\" title=\"Link to this heading\">#</a></h1><p>You can utilize features and commands of Transformer Engine on chips supported by TransformerEngine-FL. Please refer to the <a class=\"reference external\" href=\"https://docs.nvidia.com/deeplearning/transformer-engine/user-guide/index.html\">Transformer Engine Documentation</a> for details.</p>", "a[href=\"#multi-platform-build-and-testing\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Build and Testing<a class=\"headerlink\" href=\"#multi-platform-build-and-testing\" title=\"Link to this heading\">#</a></h1><p>This guide covers building TransformerEngine-FL and validating it with an end-to-end training workflow across CUDA (NVIDIA), MetaX, Hygon, Ascend, and T-Head PPU. It focuses on the parts that are specific to this component \u2014 the operator backend tiers, the vendor backends, and the attention backends \u2014 and on how to tell a healthy build from a broken one.</p><p>For the training orchestration around it, see <a class=\"reference external\" href=\"https://github.com/flagos-ai/Megatron-LM-FL\">Megatron-LM-FL</a> and <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagScale\">FlagScale</a>.</p>", "a[href=\"#install-flashattention\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3 Install FlashAttention<a class=\"headerlink\" href=\"#install-flashattention\" title=\"Link to this heading\">#</a></h3><p>On CUDA, install FlashAttention after entering the container:</p>", "a[href=\"#hygon\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">9.2 Hygon<a class=\"headerlink\" href=\"#hygon\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">gradient_accumulation_fusion</span></code> requires APEX CUDA extensions</strong> \u2014 disable it in the task configuration:</p>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">9.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#backend-layout\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Backend layout<a class=\"headerlink\" href=\"#backend-layout\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL dispatches every operator through three tiers. Knowing which tier a failure comes from is the fastest way to localize a problem.</p>", "a[href=\"#run-the-deepseek-v3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Run the DeepSeek-V3 training test<a class=\"headerlink\" href=\"#run-the-deepseek-v3-training-test\" title=\"Link to this heading\">#</a></h2><p>Requires 4 GPUs. Uses expert parallelism and per-operator backend configuration for grouped GEMM.</p>", "a[href=\"#operator-selection\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Operator selection<a class=\"headerlink\" href=\"#operator-selection\" title=\"Link to this heading\">#</a></h2><p>Operator selection is driven by three model arguments in the task-level YAML:</p>", "a[href=\"#expected-output\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Expected output<a class=\"headerlink\" href=\"#expected-output\" title=\"Link to this heading\">#</a></h3><p>A healthy single-card run on Ascend (Qwen3, <code class=\"docutils literal notranslate\"><span class=\"pre\">global_batch_size:</span> <span class=\"pre\">32</span></code>):</p>", "a[href=\"#t-head-ppu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">9.4 T-Head PPU<a class=\"headerlink\" href=\"#t-head-ppu\" title=\"Link to this heading\">#</a></h3><p><strong>FlagTree and FlagGems cannot be compiled on <code class=\"docutils literal notranslate\"><span class=\"pre\">/workspace</span></code></strong> \u2014 see the note in section 5. Build from local disk.</p><p><strong>FlagCX is not enabled</strong> \u2014 the FlagCX path is known to fail on this platform; keep <code class=\"docutils literal notranslate\"><span class=\"pre\">distributed_backend</span></code> on the vendor collective library.</p>", "a[href=\"#clone-the-repositories\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 Clone the repositories<a class=\"headerlink\" href=\"#clone-the-repositories\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#install-the-flagos-compiler-and-operator-library\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Install the FlagOS compiler and operator library<a class=\"headerlink\" href=\"#install-the-flagos-compiler-and-operator-library\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL\u2019s FlagOS tier is built on FlagGems, which in turn needs FlagTree as its compiler. Install both before enabling <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl_prefer:</span> <span class=\"pre\">flagos</span></code>.</p>", "a[href=\"#ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">9.3 Ascend<a class=\"headerlink\" href=\"#ascend\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError:</span> <span class=\"pre\">'&lt;'</span> <span class=\"pre\">not</span> <span class=\"pre\">supported</span> <span class=\"pre\">between</span> <span class=\"pre\">instances</span> <span class=\"pre\">of</span> <span class=\"pre\">'NoneType'</span> <span class=\"pre\">and</span> <span class=\"pre\">'int'</span></code></strong> \u2014 on NPU devices <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda.get_device_properties(...).major</span></code> returns <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code>, so the Blackwell check <code class=\"docutils literal notranslate\"><span class=\"pre\">get_device_arch_version()</span> <span class=\"pre\">&lt;</span> <span class=\"pre\">10</span></code> fails. The code path is only reached when <code class=\"docutils literal notranslate\"><span class=\"pre\">tensor_model_parallel_size</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">context_parallel_size</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code>, which is why single-card runs pass and multi-card runs fail. Patch <code class=\"docutils literal notranslate\"><span class=\"pre\">get_device_arch_version()</span></code> so non-NVIDIA devices return a value below 10:</p>", "a[href=\"#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">9. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>9.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> imports <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code> from Triton, which FlagTree does not provide. Add a compatibility shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#build-and-install-transformerengine-fl\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Build and install TransformerEngine-FL<a class=\"headerlink\" href=\"#build-and-install-transformerengine-fl\" title=\"Link to this heading\">#</a></h2><p>On NVIDIA, build against the CUDA toolkit:</p>", "a[href=\"#run-the-qwen3-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Run the Qwen3 training test<a class=\"headerlink\" href=\"#run-the-qwen3-training-test\" title=\"Link to this heading\">#</a></h2><p>The test job is a Qwen3 training run driven by FlagScale, with TransformerEngine-FL supplying the transformer operators.</p><p>First prepare the dataset and tokenizer:</p>", "a[href=\"#get-the-image-and-start-the-container\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 Get the image and start the container<a class=\"headerlink\" href=\"#get-the-image-and-start-the-container\" title=\"Link to this heading\">#</a></h3><p>Go to the <a class=\"reference external\" href=\"https://flagos.io/Home\">FlagOS main page</a>, pick the image for your hardware from the download list in the middle of the page, and follow the on-page instructions to pull the image, enter the container, and start it.</p><p>Before installing the packages below, check inside the container that your device is visible (section 2 lists the command for each platform).</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
